const strTime=t=>new Date(t).toISOString().slice(0,10);
const MODAL_TRIGGER=new WeakMap();
const MODAL_STACK=[];
let theme=store.read('appearance','system');
if(!['light','dark','system'].includes(theme))theme='system';
function applyTheme(){if(theme==='system')document.documentElement.removeAttribute('data-theme');else document.documentElement.dataset.theme=theme;const b=$('themeButton');if(b)b.setAttribute('aria-label','Appearance: '+theme+'. Activate to switch.');}
applyTheme();
const palette=()=>{const c=getComputedStyle(document.documentElement);return {blue:c.getPropertyValue('--blue').trim(),ink:c.getPropertyValue('--ink').trim(),muted:c.getPropertyValue('--muted').trim(),line:c.getPropertyValue('--line').trim(),bg:c.getPropertyValue('--surface').trim()}};
let toastTimer;
function toast(text){const e=$('toast');if(!e)return;clearTimeout(toastTimer);e.textContent=text;e.hidden=false;toastTimer=setTimeout(()=>{e.hidden=true},4200)}
function prepareModalFocus(d){for(const e of d.querySelectorAll('button,a[href],input[type=checkbox],input[type=radio],summary'))if(!e.hasAttribute('tabindex'))e.setAttribute('tabindex','0');}
function modalOpen(id){const d=$(id);if(!d)return;prepareModalFocus(d);if(!d.open){MODAL_TRIGGER.set(d,document.activeElement);d.showModal();MODAL_STACK.push(d);}}
function modalClose(id){const d=$(id);if(d?.open)d.close()}
for(const d of document.querySelectorAll('dialog')){
 d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
 d.addEventListener('close',()=>{const i=MODAL_STACK.indexOf(d);if(i>=0)MODAL_STACK.splice(i,1);const p=$('tipPopover');if(p&&d.contains(p)){if(p.matches(':popover-open'))p.hidePopover();document.body.appendChild(p)}const target=MODAL_TRIGGER.get(d);if(target?.isConnected)target.focus({preventScroll:true});if(d.id==='voyageDialog'){DETAIL_ID=null;destroyDetailChart();writeURL()}});
}
async function copyText(text,success){try{await navigator.clipboard.writeText(text);toast(success);return true}catch{
 const t=document.createElement('textarea');t.value=text;t.setAttribute('aria-label','Text to copy');Object.assign(t.style,{position:'fixed',left:'-9999px',top:'0'});document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch{}t.remove();if(ok){toast(success);return true}
 const d=$('statusDialog');if(d){$('statusTitle').textContent='Copy this text';$('statusContent').innerHTML=`<p class="section-caption">Your browser blocked automatic copying. Select and copy the text below.</p><textarea class="quote-preview" aria-label="Text to copy" style="width:100%;height:240px">${esc(text)}</textarea>`;modalOpen('statusDialog');$('statusContent').querySelector('textarea').select()}else toast('Copying is unavailable in this browser.');return false;
}}
let HELP=null,HELP_ID='start';
const helpPromise=fetch(new URL('assets/help.json',base)).then(r=>{if(!r.ok)throw Error('Help HTTP '+r.status);return r.json()}).then(d=>{if(!Array.isArray(d.articles))throw Error('Invalid help content');HELP=d;return d}).catch(e=>{console.warn('ORION help:',e.message);return null});
function renderHelp(query='',requested){if(!HELP){$('helpArticle').innerHTML='<p>The searchable guide could not load. Read the <a href="GUIDE.md">complete text guide</a>.</p>';return}
 const q=norm(query).trim();const docs=HELP.articles.filter(a=>!q||norm(a.title+' '+a.intro+' '+a.blocks.map(b=>b.heading+' '+b.text).join(' ')).includes(q));
 if(requested)HELP_ID=requested;
 if(!docs.some(a=>a.id===HELP_ID))HELP_ID=docs[0]?.id;
 const nav=$('helpNav');nav.replaceChildren();let group='';
 for(const a of docs){if(group!==a.section){const p=document.createElement('div');p.className='help-group-label';p.textContent=a.section;nav.appendChild(p);group=a.section}const b=document.createElement('button');b.className='help-topic';b.dataset.helpTopic=a.id;b.textContent=a.title;if(a.id===HELP_ID)b.setAttribute('aria-current','page');nav.appendChild(b)}
 const a=docs.find(x=>x.id===HELP_ID);if(!a){$('helpArticle').innerHTML='<div class="empty-state"><h3>No matching guide topic</h3><p>Try “prices”, “dates”, “saved” or “updates”.</p></div>';return}
 $('helpArticle').innerHTML=`<div class="eyebrow">${esc(a.section)}</div><h3>${esc(a.title)}</h3><p class="article-intro">${esc(a.intro)}</p>${a.blocks.map(b=>`<section><h4>${esc(b.heading)}</h4><p>${esc(b.text)}</p></section>`).join('')}<div class="article-footer"><span>ORION user guide · No booking actions</span><a href="help.html?topic=${encodeURIComponent(a.id)}" target="_blank" rel="noopener noreferrer">Open this topic separately ${icon('arrow-up-right','sm')}</a></div>`;
}
async function openHelp(topic='start'){await helpPromise;if($('tipPopover')?.matches(':popover-open'))$('tipPopover').hidePopover();if($('helpSearch'))$('helpSearch').value='';renderHelp('',topic);if(document.body.dataset.mode!=='help')modalOpen('helpDialog');else history.replaceState(null,'','?topic='+encodeURIComponent(topic));}
let tipTrigger=null;
async function openTip(key,trigger){await helpPromise;const x=HELP?.tips[key];if(!x)return;const p=$('tipPopover');if(!p){openHelp(x.topic);return}const host=trigger.closest('dialog')||document.body;if(p.parentElement!==host){if(p.matches(':popover-open'))p.hidePopover();host.appendChild(p)}tipTrigger?.setAttribute('aria-expanded','false');tipTrigger=trigger;trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls','tipPopover');$('tipTitle').textContent=x.title;$('tipText').textContent=x.text;$('tipMore').dataset.topic=x.topic;if(!p.matches(':popover-open'))p.showPopover();const rect=trigger.getBoundingClientRect();requestAnimationFrame(()=>{const box=p.getBoundingClientRect();const left=Math.max(12,Math.min(window.innerWidth-box.width-12,rect.left-15));let top=rect.bottom+9;if(top+box.height>window.innerHeight-12)top=Math.max(12,rect.top-box.height-9);p.style.left=left+'px';p.style.top=top+'px';})}
$('tipPopover')?.addEventListener('toggle',e=>{if(e.newState==='closed')tipTrigger?.setAttribute('aria-expanded','false')});
$('tipMore')?.addEventListener('click',()=>openHelp($('tipMore').dataset.topic));
$('helpSearch')?.addEventListener('input',e=>renderHelp(e.target.value));
document.addEventListener('click',e=>{const t=e.target.closest('[data-help-topic]');if(t){renderHelp($('helpSearch').value,t.dataset.helpTopic);$('helpArticle').focus({preventScroll:true});if(document.body.dataset.mode==='help')history.replaceState(null,'','?topic='+encodeURIComponent(t.dataset.helpTopic))}const c=e.target.closest('[data-close]');if(c)modalClose(c.dataset.close)});
if(document.body.dataset.mode==='help'){
 document.addEventListener('click',e=>{if(e.target.closest('[data-action="theme"]')){theme=theme==='system'?'light':theme==='light'?'dark':'system';store.write('appearance',theme);applyTheme();toast('Appearance: '+theme)}});
 helpPromise.then(()=>renderHelp('',new URLSearchParams(location.search).get('topic')||'start'));return;
}

const F=globalThis.ORIONFilters;
const C=globalThis.ORIONCatalogue;
let CATALOGUE_SEQUENCE=0;
const DEFAULT=F.empty();
let state=F.empty(),DATA=null,PRODUCTS=[],BY_ID=new Map(),PAGE_SIZE=96;
let saved=new Set(Array.isArray(store.read('saved',[]))?store.read('saved',[]):[]);
let compared=new Set(Array.isArray(store.read('compare',[]))?store.read('compare',[]).slice(0,3):[]);
let selectedSize=store.read('pageSize','96');if(!['48','96','240','all'].includes(String(selectedSize)))selectedSize='96';PAGE_SIZE=selectedSize==='all'?10000:Number(selectedSize);if($('pageSize'))$('pageSize').value=String(selectedSize);
let layout=store.read('layout','cards');if(!['cards','list'].includes(layout))layout='cards';
const W=window.OrionWatches;
let watches=store.read('watches',[]),watchEvents=store.read('watchEvents',[]),watchStates=[],WATCH_EDIT_ID=null;
if(!Array.isArray(watches))watches=[];if(!Array.isArray(watchEvents))watchEvents=[];
watches=watches.filter(x=>x&&typeof x.id==='string').slice(0,100);watchEvents=watchEvents.filter(x=>x&&typeof x.id==='string').slice(0,100);
let DETAIL_ID=null,DETAIL_TAB='overview',DETAIL=null,DETAIL_COLUMN='',DETAIL_SEQUENCE=0,DETAIL_RENDER=0;
const detailFiles=new Map();let detailChart=null,calendarChart=null,CALENDAR_OPEN=false;
let helpInit=false,initialLoad=true;
let URL_RESTORING=false,REPLACE_NEXT_URL=false,SEARCH_ENTRY_STARTED=false;
let HISTORY_SOURCE='supplier',ARCHIVE_SERIES='',HISTORY_RANGE='all';
function snapshotAge(){const t=Date.parse(DATA?.feed?.observed_at);return Number.isFinite(t)?Math.max(0,(Date.now()-t)/3600000):Infinity}
function readURL(){const p=new URLSearchParams(location.search);state=F.fromParams(p);return p;}
function writeURL(forceReplace=false){
 if(!DATA||URL_RESTORING)return;
 const p=F.toParams(state);
 if(DETAIL_ID){
  p.set('voyage',DETAIL_ID);if(DETAIL_TAB!=='overview')p.set('tab',DETAIL_TAB);
  if(DETAIL_TAB==='history'){
   if(HISTORY_SOURCE==='archive'){p.set('history_source','archive');p.set('history_range',HISTORY_RANGE);if(ARCHIVE_SERIES)p.set('history_series',ARCHIVE_SERIES)}
   else if(DETAIL_COLUMN)p.set('history_column',DETAIL_COLUMN);
  }
 }
 const target=location.pathname+(p.size?'?'+p.toString():'');
 if(target!==location.pathname+location.search){
  const method=initialLoad||REPLACE_NEXT_URL||forceReplace?'replaceState':'pushState';
  history[method]({orion:true},'',target);
 }
 REPLACE_NEXT_URL=false;
}
function restoreEvidenceParams(p){
 HISTORY_SOURCE=p.get('history_source')==='archive'?'archive':'supplier';
 HISTORY_RANGE=['30','90','365','all'].includes(p.get('history_range'))?p.get('history_range'):'all';
 ARCHIVE_SERIES=HISTORY_SOURCE==='archive'?(p.get('history_series')||''):'';
}

function populateSelect(id,items,label){const e=$(id);if(!e)return;const keep=e.value;e.replaceChildren();const d=document.createElement('option');d.value='';d.textContent=label;e.appendChild(d);[...new Set(items.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b))).forEach(v=>{const op=document.createElement('option');op.value=v;op.textContent=v;e.appendChild(op)});e.value=keep;}
function syncFields(){$('query').value=state.q;$('regionLabel').textContent=state.regions.length===1?regionLabel(state.regions[0]):state.regions.length?state.regions.length+' destinations':'Everywhere';$('sort').value=state.sort;}
function fare(r){return F.fare(r,state)}
function drop(r){if(state.cabin){const x=r.changes?.[state.cabin];return x&&x[0]>0?{column:state.cabin,pct:x[0],current:x[1],previous:x[2]}:null}return r.drop?.pct>0?r.drop:null}
function matchesFor(r,s){if(s.view==='saved'&&!saved.has(r.id))return false;if(s.q&&!norm(s.q).trim().split(/\s+/).every(t=>r._search.includes(t)))return false;if(!F.matches(r,s))return false;if(s.view==='drops'){const d=s.cabin?r.changes?.[s.cabin]?.[0]:r.drop?.pct;if(!(d>0))return false}if(s.view==='archive'&&!r.archive_count)return false;if(s.evidence==='agency'&&!r.retail_advert_count)return false;if(s.evidence==='verified')return false;return true;}
function matches(r){return matchesFor(r,state)}
function filtered(){return sortProducts(PRODUCTS.filter(matches))}
function sortProducts(items){return items.sort((x,y)=>{
 const xp=fare(x)?.amount??Infinity,yp=fare(y)?.amount??Infinity;let n=0;
 if(state.sort==='price')n=xp-yp;
 else if(state.sort==='daily')n=xp/x.duration-yp/y.duration;
 else if(state.sort==='latest')n=y.departure.localeCompare(x.departure);
 else if(state.sort==='drop')n=(drop(y)?.pct||0)-(drop(x)?.pct||0);
 else if(state.sort==='history')n=(y.archive_dates_count||0)-(x.archive_dates_count||0)||(x.archive_oldest||'9999').localeCompare(y.archive_oldest||'9999');
 else if(state.sort==='oldest')n=(x.archive_oldest||'9999').localeCompare(y.archive_oldest||'9999');
 return n||x.departure.localeCompare(y.departure)||xp-yp;
})}

function noticeTitle(){
 if(state.view==='saved')return ['The voyages<br>you <em>come back to.</em>','A personal collection of possibilities. Keep the ones that speak to you, then compare the details.','Your personal shortlist'];
 if(state.view==='drops')return ['A change in price.<br>A new <em>possibility.</em>','Follow genuine changes in published categories. Open the dated evidence, then confirm the complete quote.','A closer look at price drops'];
 if(state.view==='archive')return ['Every price<br>has a <em>past.</em>','Explore recovered advertisements, inspect their dates and trace the story behind today’s guide.','The earlier-price archive'];
 if(state.view==='offers')return ['The little extras.<br>The <em>full picture.</em>','Understand the benefits, eligibility and conditions that can shape your voyage.','Offers to understand'];
 return ['Find your voyage.<br>Know the price.','Independent Windstar cruise research. Prices are GBP guides for two, not bookable quotes.','A clearer shortlist starts here.'];
}
function regionLabel(value){return ({'N. Europe':'Northern Europe','Greek':'Greek Islands','Latin':'Central America','Canada-Ne':'Canada & New England','Trans-Ocean':'Ocean crossings'})[value]||value;}
function regionScene(value){if(value==='Mediterranean')return {key:'mediterranean',image:'mediterranean-card.jpg'};if(value==='Tahiti'||value==='South Pacific')return {key:'tahiti',image:'tahiti-card.jpg'};if(value==='N. Europe')return {key:'north',image:'northern-europe-card.jpg'};return {key:({'Greek':'greek','Alaska':'alaska','Caribbean':'caribbean','Asia':'asia','Latin':'latin','Trans-Ocean':'ocean','Canada-Ne':'canada'})[value]||'ocean',image:null};}
function renderDiscovery(){
 const rail=$('destinationRail');if(!rail)return;
 if($('heroDropCount'))$('heroDropCount').textContent=fmtNum.format(PRODUCTS.filter(r=>r.drop?.pct>0).length);
 $('destinationBrowser').hidden=!['all','drops','archive'].includes(state.view);
 const regions=[['Mediterranean','Warm harbours. A slower rhythm.','01'],['Tahiti','A little further from the everyday.','02'],['N. Europe','Wide skies. Wilder coastlines.','03']];
 rail.innerHTML=regions.map(([region,caption,num])=>{const n=PRODUCTS.filter(r=>r.region===region).length,scene=regionScene(region);return `<button class="destination-option ${state.regions.includes(region)?'is-active':''}" data-destination="${esc(region)}" aria-pressed="${state.regions.includes(region)}"><span class="destination-thumb region-${scene.key}"><img src="assets/imagery/${scene.image}" alt="" width="640" height="420" loading="lazy" decoding="async"><span class="destination-number" aria-hidden="true">${num}</span></span><span class="destination-description"><strong>${esc(regionLabel(region))}</strong><small>${caption}</small><span class="destination-count">${fmtNum.format(n)} departures ${icon('arrow-right','sm')}</span></span></button>`}).join('');
 const hero=$('heroFeature');if(!hero)return;hero.hidden=!['all','drops','archive'].includes(state.view);
 const chosen=PRODUCTS.filter(r=>matchesFor(r,{...state,view:'all',evidence:'all'})&&r.drop?.pct>=10&&r.drop.pct<=40&&r.duration<=14&&r.departure>='2027-01-01'&&r.archive_count>0).sort((a,b)=>b.drop.pct-a.drop.pct||a.departure.localeCompare(b.departure))[0];
 if(state.view==='archive'&&DATA.archive){hero.innerHTML=`<div class="note-label">${icon('clock-3')}<span>THE PRICE<br>JOURNAL</span></div><div class="note-story"><h2>${fmtNum.format(DATA.archive.observations)} earlier observations. A little more perspective.</h2><p>${fmtNum.format(DATA.archive.products_with_archive)} matched sailings. Partial archive coverage; missing prices are never estimated.</p></div><button class="text-link" data-action="archive-coverage">Explore the evidence ${icon('arrow-up-right')}</button>`;}
 else if(chosen){const d=chosen.drop;hero.innerHTML=`<div class="note-label">${icon('trending-down')}<span>IN THE<br>PRICE JOURNAL</span></div><div class="note-story"><div class="note-meta">${esc(chosen.ship)} · ${esc(day(chosen.departure))} · Category ${esc(d.column)}</div><h2>${esc(chosen.itinerary)}</h2><p><strong>${pct(d.pct)} recorded decrease</strong> · ${money(d.previous)} → ${money(d.current)} assumed per person. Confirm the price basis, availability and final costs.</p></div><button class="text-link" data-action="voyage" data-id="${esc(chosen.id)}" data-tab="history" data-column="${esc(d.column)}">Read the price story ${icon('arrow-up-right')}</button>`;}
 else{hero.innerHTML=`<div class="note-label">${icon('compass')}<span>AN INDEPENDENT<br>POINT OF VIEW</span></div><div class="note-story"><h2>A promising price deserves a closer look.</h2><p>Compare the same sailing, cabin and inclusions. Our evidence helps you ask better questions.</p></div><button class="text-link" data-action="help" data-topic="verification">Our approach ${icon('arrow-up-right')}</button>`;}
}

function renderChips(){const chips=[];for(const [key,label] of [['ships','ship'],['regions','region']])for(const value of state[key]){const text=key==='regions'?regionLabel(value):value;chips.push(`<button class="chip" data-remove-choice="${key}" data-value="${esc(value)}" aria-label="Remove ${esc(text)}">${esc(text)}${icon('x')}</button>`)}
 const range=(a,b,suffix)=>a&&b?(a===b?a:a+'–'+b)+suffix:a?'From '+a+suffix:b?'Up to '+b+suffix:'';
 const labels={q:state.q?'Search: '+state.q:'',from:state.from?'Departs from '+day(state.from):'',to:state.to?'Ends by '+day(state.to):'',length:range(state.minDays,state.maxDays,' days'),budgetRange:range(state.minBudget?fmtGBP.format(Number(state.minBudget)):'',state.budget!==''?fmtGBP.format(Number(state.budget)):'',' for two'),kind:state.kind,cabin:state.cabin?'Category '+state.cabin:''};
 for(const [key,text] of Object.entries(labels))if(text)chips.push(`<button class="chip" data-remove-filter="${key}" aria-label="Remove ${esc(text)}">${esc(text)}${icon('x')}</button>`);
 if(chips.length)chips.push('<button class="chip-clear" data-action="reset">Clear all</button>');$('chips').innerHTML=chips.join('');const n=state.ships.length+state.regions.length+Object.values(labels).filter(Boolean).length;$('filterCount').textContent=n;$('filterCount').hidden=!n;$('whenLabel').textContent=state.from||state.to?'Dates set':'Any dates';}
function renderHeader(){const [title,caption,section]=noticeTitle();document.body.dataset.section=state.view;document.querySelectorAll('[data-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.group===state.group)));if($('archiveBrief'))$('archiveBrief').hidden=state.view!=='archive';if(state.view==='archive')renderArchiveBrief();$('pageTitle').innerHTML=title;$('pageIntro').innerHTML=caption;$('exploreTitle').textContent=section;$('sectionSub').textContent=state.view==='drops'?'See the change, compare your dates, then request a quote.':state.view==='saved'?'Your saved departures. Filter, compare or export them.':state.view==='archive'?'Earlier advertised prices, with dates you can inspect.':'Choose a destination or start with the evidence.';document.querySelectorAll('[data-view]').forEach(b=>{if(b.closest('.main-nav')){if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}});$('savedCount').textContent=saved.size;$('savedNotice').hidden=state.view!=='saved';$('exportButton').hidden=state.view!=='saved';$('exportButton').disabled=!saved.size;$('exploreSection').hidden=state.view==='offers';$('offersSection').hidden=state.view!=='offers';document.querySelectorAll('[data-quick]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quick===state.evidence)));document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layout===layout)));}
function saveButton(r,large=false){const on=saved.has(r.id);return `<button class="${large?'button secondary':'icon-btn save-button'}${on?' selected':''}" data-action="save" data-id="${esc(r.id)}" aria-pressed="${on}" aria-label="${on?'Unsave':'Save'} ${esc(r.itinerary)}">${icon(on?'bookmark-check':'bookmark')}${large?`<span class="label-hide">${on?'Saved':'Save'}</span>`:''}</button>`}
