function card(r){
 const f=fare(r),chosenChange=r.changes?.[f?.column],d=chosenChange?.[0]>0?{column:f.column,pct:chosenChange[0],current:chosenChange[1],previous:chosenChange[2]}:drop(r),dates=r._matchingDates??(state.from||state.to?dateOptions(r).length:DATA.families?.[r.family_id]||1),scene=regionScene(r.region),label=regionLabel(r.region);
 return `<article class="voyage-card image-voyage"><div class="card-visual region-${esc(scene.key)}">${scene.image?`<img src="assets/imagery/${scene.image}" alt="" loading="lazy" decoding="async" width="640" height="420">`:`<div class="region-art" aria-hidden="true"><svg viewBox="0 0 600 350"><path class="atlas-land" d="M-20 20C95 0 55 155 173 132S235 15 330 50 325 185 420 169 480 86 620 110V-20H-20Z"/><path d="M-25 60C70 40 62 197 180 165S240 55 323 88 350 214 430 205 500 130 620 145M-25 95C55 95 70 236 190 202S240 96 320 128 370 253 450 240 500 175 620 180M-25 135C40 145 85 272 210 242S260 139 340 171 380 290 470 281 520 208 620 220"/><path class="atlas-course" d="M95 260Q260 335 477 140"/><circle cx="95" cy="260" r="7"/><circle cx="477" cy="140" r="7"/></svg>${icon('compass')}<span>THE ${esc(label.toUpperCase())} COLLECTION</span></div>`}<div class="visual-top"><span class="ship-label">${icon('ship')}${esc(r.ship)}</span>${saveButton(r)}</div><span class="visual-region">${esc(label)}</span>${dates>1?`<button class="visual-dates" data-action="voyage" data-id="${esc(r.id)}" data-tab="dates">${dates} dates ${icon('arrow-up-right','sm')}</button>`:''}</div><div class="card-main"><div class="card-heading"><div class="product-kind">${r._isGroup?'LOWEST MATCHING DEPARTURE':r.kind==='Cruise'?'THE SMALL-SHIP COLLECTION':r.kind==='Collector / combined cruise'?'A COMBINED VOYAGE':'CRUISE + LAND'}</div><h3 class="card-title"><button data-action="voyage" data-id="${esc(r.id)}">${esc(r.itinerary)}</button></h3></div><p class="card-route">${esc(r.from_port)} <span aria-label="to">→</span> ${esc(r.to_port)}</p><div class="card-itinerary-meta"><div class="card-date">${icon('calendar-days')}${esc(day(r.departure))}<span class="date-sep">·</span>${esc(r.duration)} published days</div><div class="trip-end-date" data-end-date="${esc(F.endDate(r)||'')}">${esc(tripEndLabel(r))}</div></div><div class="card-price-row"><div><div class="price-caption">Cruise guide for two ${info('guide','What is included in this guide?')}</div><div class="price-figure">${money(f?.amount*2)}<small>GBP</small></div></div><span class="quote-state">Final quote<br>to confirm</span></div>${d?`<button class="price-movement" data-action="voyage" data-id="${esc(r.id)}" data-tab="history" data-column="${esc(d.column)}">${icon('trending-down')}<span>${d.column===f?.column?'Recorded decrease':'Another category down'} <strong>${pct(d.pct)}</strong></span>${icon('arrow-up-right','sm')}</button>`:`<div class="price-movement movement-neutral">${icon('clock-3')}<span>A dated guide. A quote to confirm.</span></div>`}<div class="evidence-trail">${r.retail_advert_count?`<button data-action="voyage" data-id="${esc(r.id)}" data-tab="prices">Compare sellers ${icon('arrow-up-right','sm')}</button>`:'<span>Seller quote needed</span>'}${r.archive_count?`<button class="archive-tag" data-action="open-archive" data-id="${esc(r.id)}">Earlier prices${r.archive_dates_count>1?' · '+r.archive_dates_count+' dates':''} ${icon('clock-3','sm')}</button>`:''}</div></div><div class="card-actions"><button class="button secondary" data-action="voyage" data-id="${esc(r.id)}">Explore this voyage ${icon('arrow-right','sm')}</button>${compareControl(r)}</div></article>`;
}

function listRows(rows){return `<div class="list-wrap"><table class="data-table"><caption class="sr-only">Matching voyage guides and evidence</caption><thead><tr><th scope="col">Voyage</th><th scope="col">Departure</th><th scope="col">Guide for 2</th><th scope="col">Evidence</th><th scope="col">Shortlist</th></tr></thead><tbody>${rows.map(r=>{const d=drop(r);return `<tr><td><button class="list-title" data-action="voyage" data-id="${esc(r.id)}">${esc(r.itinerary)}</button><small>${esc(r.ship)} · ${esc(r.region)}</small></td><td>${esc(day(r.departure))}<small data-end-date="${esc(F.endDate(r)||'')}">${esc(tripEndLabel(r))}</small><small>${r.duration} published days</small></td><td class="money"><strong>${money(fare(r)?.amount*2)}</strong><small>Unverified estimate</small></td><td>${d?`<button class="evidence-badge" data-action="voyage" data-id="${esc(r.id)}" data-tab="history" data-column="${esc(d.column)}">${icon('trending-down')}${pct(d.pct)} recorded move</button>`:'No recorded decrease'}<small>${r.retail_advert_count||0} seller records</small>${r.archive_count?`<button class="archive-tag" data-action="open-archive" data-id="${esc(r.id)}">${r.archive_count} archived prices</button>`:''}</td><td><div class="row-actions">${saveButton(r)}${compareControl(r)}</div></td></tr>`}).join('')}</tbody></table></div>`}
function emptyMarkup(){if(state.evidence==='verified')return `<div class="empty-state">${icon('shield-check')}<h3>No verified exceptional bargains yet.</h3><p>Published price drops are useful leads. A confirmed saving needs the same cabin, full UK costs and real availability, checked against an independent seller.</p><button class="button secondary" data-action="unverify">Explore the published guides ${icon('arrow-right')}</button> <button class="button quiet" data-action="help" data-topic="verification">Read the verification standard</button></div>`;if(state.view==='saved'&&saved.size&&![...saved].some(id=>BY_ID.has(id)))return `<div class="empty-state">${icon('bookmark')}<h3>Your saved voyages are retained.</h3><p>They are absent from this edition or their departure has passed. This does not confirm that they sold out. They will reappear here if listed again.</p><button class="button primary" data-view="all">Explore current voyages</button></div>`;if(state.view==='saved'&&!saved.size)return `<div class="empty-state">${icon('bookmark')}<h3>Keep something worth coming back to.</h3><p>Bookmark a voyage while exploring and it will appear here. Your shortlist stays on this browser; it does not create an alert or booking.</p><button class="button primary" data-view="all">Explore voyages ${icon('arrow-right')}</button></div>`;return `<div class="empty-state">${icon('sliders-horizontal')}<h3>A little more room to explore?</h3><p>No published departures match this combination. Try a wider date range, another region or a higher cruise-guide budget.</p><button class="button secondary" data-action="reset">Clear these filters</button></div>`}
function renderPagination(total){const pages=Math.ceil(total/PAGE_SIZE),e=$('pagination');e.hidden=pages<=1;if(pages<=1)return;let nums=[1,pages,state.page-1,state.page,state.page+1].filter(n=>n>=1&&n<=pages);nums=[...new Set(nums)].sort((a,b)=>a-b);let last=0,buttons='';for(const n of nums){if(n>last+1)buttons+='<span aria-hidden="true">…</span>';buttons+=`<button class="page-button" data-page="${n}" ${n===state.page?'aria-current="page"':''} aria-label="Page ${n}">${n}</button>`;last=n}e.innerHTML=`<span>${fmtNum.format((state.page-1)*PAGE_SIZE+1)}–${fmtNum.format(Math.min(total,state.page*PAGE_SIZE))} of ${fmtNum.format(total)} ${state.group==='itineraries'?'itineraries':'departures'}</span><div class="page-controls"><button class="page-button" data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="Previous page">${icon('chevron-left')}</button>${buttons}<button class="page-button" data-page="${state.page+1}" ${state.page===pages?'disabled':''} aria-label="Next page">${icon('chevron-right')}</button></div>`}
function updateCompareTray(){const n=compared.size;$('compareTray').hidden=!n;$('compareCount').textContent=n+' voyage'+(n===1?'':'s')+' selected';$('compareButtonCount').textContent=n;$('compareNames').textContent=[...compared].map(id=>BY_ID.get(id)?.itinerary).filter(Boolean).join(' · ');}
function render({scroll=false}={}){
 if(!DATA)return;renderHeader();renderDiscovery();syncFields();renderChips();updateCompareTray();
 if(state.view==='offers'){renderOffers();writeURL();return}
 const all=filtered(),a=displayProducts(all);state.page=Math.min(state.page,Math.max(1,Math.ceil(a.length/PAGE_SIZE)));
 const page=a.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE),noun=state.group==='itineraries'?'itinerar'+(a.length===1?'y':'ies'):'departure'+(a.length===1?'':'s');
 $('resultCount').textContent=fmtNum.format(a.length)+' '+noun;
 $('resultNote').textContent=state.group==='itineraries'?fmtNum.format(all.length)+' dates. Lowest matching departure shown.':'Estimated cruise prices for two · GBP';
 $('results').dataset.large=String(PAGE_SIZE>240);$('results').className=layout==='cards'?'voyage-grid':'voyage-grid list-mode';$('results').innerHTML=a.length?(layout==='cards'?page.map(card).join(''):listRows(page)):emptyMarkup();renderPagination(a.length);if(CALENDAR_OPEN)renderCalendar(all);writeURL();if(scroll)$('resultCount').scrollIntoView({behavior:'auto',block:'start'});
}

function resetFilters(){const view=state.view==='offers'?'all':state.view;state={...DEFAULT,view,sort:view==='drops'?'drop':'date'};render();}
function nav(view){state.view=view;state.evidence='all';state.page=1;state.sort=view==='drops'?'drop':view==='archive'?'history':'date';if(view==='saved'){state={...DEFAULT,view:'saved'}}render();}
function toggleSaved(id){if(!BY_ID.has(id))return;if(saved.has(id)){saved.delete(id);toast('Removed from your saved voyages.')}else{saved.add(id);toast('Saved on this browser. No alert or booking created.')}if(!store.write('saved',[...saved]))toast('Saved for this visit only. Browser storage is unavailable.');render();if($('voyageDialog').open)updateVoyageFooter();}
function toggleCompare(id){if(compared.has(id))compared.delete(id);else if(compared.size<3)compared.add(id);else{toast('Compare up to three voyages. Remove one before adding another.');return}store.write('compare',[...compared]);render();if($('voyageDialog').open)updateVoyageFooter();}
const RANGE_FIELDS=['from','to','minDays','maxDays','minBudget','budget','kind','cabin'];
const fieldID=k=>'filter'+k[0].toUpperCase()+k.slice(1);
function renderChoices(){for(const [key,container,field] of [['ships','shipChoices','ship'],['regions','regionChoices','region']]){const values=[...new Set(PRODUCTS.map(r=>r[field]))].sort();$(container).innerHTML=values.map((value,i)=>`<label class="choice-option" for="${key}-${i}"><input type="checkbox" id="${key}-${i}" name="${key}" value="${esc(value)}"><span>${esc(key==='regions'?regionLabel(value):value)}</span><small>${fmtNum.format(PRODUCTS.filter(r=>r[field]===value).length)}</small></label>`).join('');}}
function readFilterDraft(){const draft={...state,ships:[...$('shipChoices').querySelectorAll('input:checked')].map(x=>x.value),regions:[...$('regionChoices').querySelectorAll('input:checked')].map(x=>x.value),page:1};for(const k of RANGE_FIELDS)draft[k]=$(fieldID(k)).value;return draft;}
function previewFilters(){const raw=readFilterDraft();for(const k of ['to','maxDays','budget'])$(fieldID(k)).setCustomValidity('');const errors=F.rangeErrors(raw);for(const [k,message] of Object.entries(errors))$(fieldID(k)).setCustomValidity(message);const invalid=[...$('filterForm').querySelectorAll('input')].find(x=>!x.validity.valid);$('rangeErrors').textContent=Object.values(errors)[0]||(invalid?'Check the highlighted number or date.':'');if(invalid){$('filterPreview').textContent='Check your range';$('applyFilters').textContent='Check filters';return false}const draft=F.normalise(raw),n=PRODUCTS.filter(r=>matchesFor(r,draft)).length;for(const [key,field,container] of [['ships','ship','shipChoices'],['regions','region','regionChoices']]){const others={...draft,[key]:[]},counts=new Map();for(const r of PRODUCTS.filter(r=>matchesFor(r,others)))counts.set(r[field],(counts.get(r[field])||0)+1);for(const input of $(container).querySelectorAll('input'))input.closest('label').querySelector('small').textContent=fmtNum.format(counts.get(input.value)||0)}$('filterPreview').textContent=n?fmtNum.format(n)+' matching voyages':'No matches. Broaden your choices.';const label='Show '+fmtNum.format(n)+' voyages '+icon('arrow-right');if($('applyFilters').innerHTML!==label)$('applyFilters').innerHTML=label;return true;}
function showFilters(focus){for(const k of RANGE_FIELDS)$(fieldID(k)).value=state[k];for(const key of ['ships','regions'])for(const input of $('filterForm').querySelectorAll(`input[name="${key}"]`))input.checked=state[key].includes(input.value);previewFilters();modalOpen('filterDialog');if(focus)requestAnimationFrame(()=>{const el=$(focus);el?.scrollIntoView({block:'center',behavior:'auto'});(el?.querySelector('input')||el)?.focus({preventScroll:true})});}

function makeQuote(r,column){return `Please send a written quote for two UK-resident adults sharing on this Windstar voyage:\n\n${r.ship}\n${r.itinerary}\nDeparture: ${day(r.departure)}\n${tripEndLabel(r)}. Please confirm the disembarkation date and any extra travel days.\nSupplier cruise ID: ${r.cruise_id}\nPublished duration: ${r.duration} days. Please confirm the actual cruise nights.\n${column?'Supplier price column of interest: '+column+'. Please confirm the exact cabin grade.':'Please specify the exact cabin grade and the lowest suitable available cabin.'}\n\nPlease confirm the final GBP total for two, including all mandatory taxes, port charges, gratuities and agency fees. Itemise any flights, hotels or transfers separately. Confirm whether All-Inclusive, loyalty or agency benefits are included and which can combine.\n\nPlease also confirm UK residency eligibility, live cabin availability, deposit, cancellation terms, quote expiry and any booking protection.\n\nI saw this as an unverified public price guide, not a final booking quote. No booking or hold is authorised by this request.`;}

async function fetchJSON(path){const u=new URL(path,base);if(u.origin!==base.origin||!u.pathname.startsWith(base.pathname))throw Error('Unexpected data location');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(u,{signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
async function detailFor(r){const path=DATA.detail_files?.[r.ship];if(!path)throw Error('No detailed evidence file is published for this ship.');if(!detailFiles.has(path)){detailFiles.set(path,fetchJSON(path).then(d=>{if(d.schema_version!==2||!d.products)throw Error('Invalid detail file');return d.products}).catch(e=>{detailFiles.delete(path);throw e}))}const records=await detailFiles.get(path),record=records[r.id];if(!record)throw Error('This product is absent from the detailed snapshot.');return {...r,...record}}
function destroyDetailChart(){if(detailChart){detailChart.destroy();detailChart=null}}
async function openVoyage(id,tab='overview',column='',historyRestore=false){if(tab!=='history'){HISTORY_SOURCE='supplier';ARCHIVE_SERIES='';HISTORY_RANGE='all';}const r=BY_ID.get(id);if(!r){toast('That departure is not present in this published catalogue.');return}DETAIL_ID=id;DETAIL_TAB=['overview','prices','dates','history'].includes(tab)?tab:'overview';DETAIL_COLUMN=column||state.cabin||drop(r)?.column||r.fares[0]?.[0]||'';DETAIL=null;const seq=++DETAIL_SEQUENCE;writeURL();$('voyageContent').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${esc(r.ship)}</span><h2 id="voyageTitle">${esc(r.itinerary)}</h2></div><button class="icon-btn close" data-close="voyageDialog" aria-label="Close voyage">${icon('x')}</button></div><div class="dialog-content"><div class="loading-state" role="status"><span class="spinner"></span><h3>Opening the evidence</h3><p>Loading only this ship's detailed prices and saved observations.</p></div></div>`;modalOpen('voyageDialog');try{const d=await detailFor(r);if(seq!==DETAIL_SEQUENCE||DETAIL_ID!==id||!$('voyageDialog').open)return;DETAIL=d;renderVoyage({replaceURL:historyRestore})}catch(e){if(seq!==DETAIL_SEQUENCE)return;$('voyageContent').innerHTML=`<div class="dialog-head"><h2 id="voyageTitle">${esc(r.itinerary)}</h2><button class="icon-btn close" data-close="voyageDialog" aria-label="Close voyage">${icon('x')}</button></div><div class="dialog-content"><div class="empty-state">${icon('cloud-off')}<h3>Details couldn't be loaded.</h3><p>The summary remains available. No missing evidence is being treated as confirmed.</p><button class="button secondary" data-action="retry-detail">Try again</button></div></div>`;console.warn('ORION detail:',e.message)}}
function detailRate(){if(!DETAIL)return null;return fare(DETAIL)||{column:DETAIL.fares[0]?.[0],amount:DETAIL.fares[0]?.[1]}}
function observedPoints(r,col){return (r.price_history?.[col]?.points||[]).filter(p=>Number.isFinite(p[1])&&p[1]>0&&Number.isFinite(Date.parse(p[0]))).sort((a,b)=>Date.parse(a[0])-Date.parse(b[0]));}
function overviewHTML(r){const f=detailRate(),points=observedPoints(r,f?.column),latest=points.at(-1)?.[1],first=points[0]?.[1],low=points.length?Math.min(...points.map(x=>x[1])):null,high=points.length?Math.max(...points.map(x=>x[1])):null;
 const now=f?.amount,comparable=points.length>1&&Number.isFinite(now)&&latest===now;
 const below=comparable&&first>now?(first-now)*2:0;
 const priceMessage=comparable?(low===high?'No change across our price checks':now===low?'At the lowest price we’ve recorded':money((now-low)*2)+' above its recorded low'):'A price to check with the seller';
 const choices=dateOptions(r).filter(v=>F.matches(v,state)).map(v=>({r:v,f:F.fare(v,{cabin:f?.column||''})})).filter(x=>x.f&&x.f.amount>0).sort((a,b)=>a.f.amount-b.f.amount||a.r.departure.localeCompare(b.r.departure));const alternative=choices.find(x=>x.r.id!==r.id&&Number.isFinite(now)&&x.f.amount<now);
 return `<section class="decision-price"><div><span class="detail-label">Estimated cruise price for two ${info('guide','About this estimated cruise price')}</span><div class="detail-price">${money(now*2)}<small>GBP</small></div><p class="price-qualification">Final cabin, inclusions and payable total require a quote.</p></div><div class="price-verdict"><span class="verdict-icon">${icon(comparable&&now===low?'trending-down':'circle-help')}</span><h3>${priceMessage}</h3><p>${below?money(below)+' below the first recorded price for this category.':comparable?'Compared with '+points.length+' actual price checks.':'We need more comparable checks before judging the trend.'}</p><small>${comparable?'Observed since '+esc(day(points[0][0]))+'. This is not a comparison with every seller.':'Current availability has not been confirmed.'}</small></div></section>
 ${points.length>1?`<section class="decision-history" aria-labelledby="decisionHistoryTitle"><div class="chart-title"><div><h3 id="decisionHistoryTitle">How this price has moved</h3><p>Estimated for two, comparing the same listed category.</p></div><div class="overview-history-links">${r.archive_prices?.length?`<button class="text-link" data-action="open-archive" data-id="${esc(r.id)}">Earlier prices</button>`:''}<button class="text-link" data-action="detail-tab" data-tab="history" data-column="${esc(f.column)}">Price history ${icon('arrow-right','sm')}</button></div></div><div class="chart-wrap overview-chart"><canvas id="overviewPriceChart" role="img" aria-label="Recorded price estimates for two in the same category; table below"></canvas></div><div class="price-endpoints"><span>Lowest recorded <strong>${money(low*2)}</strong></span><span>Highest recorded <strong>${money(high*2)}</strong></span><span>Latest recorded <strong>${money(latest*2)}</strong></span></div><details class="chart-data"><summary>View dates and exact amounts</summary><div class="table-scroll"><table class="data-table"><caption class="sr-only">Exact values behind the price overview</caption><thead><tr><th scope="col">Checked</th><th scope="col">Estimated for two</th></tr></thead><tbody>${points.map(p=>`<tr><td>${esc(dateTime(p[0]))}</td><td>${money(p[1]*2,true)}</td></tr>`).join('')}</tbody></table></div></details></section>`:''}
 <div class="decision-actions"><button class="decision-next" data-action="detail-tab" data-tab="dates"><span>${icon('calendar-days')}</span><div><strong>${alternative?'Another date is '+money((now-alternative.f.amount)*2)+' lower':(dateOptions(r).length===1?'One departure currently listed':dateOptions(r).length+' dates to compare')}</strong><small>${alternative?esc(day(alternative.r.departure))+' · Same listed category; packages may differ.':'Explore dates and prices for this voyage.'}</small></div>${icon('chevron-right','sm')}</button><button class="decision-next" data-action="detail-tab" data-tab="prices"><span>${icon('columns-3')}</span><div><strong>Compare cabins and sellers</strong><small>${r.retail_prices?.length?'View dated advertisements and request matching quotes.':'Choose your cabin and find a current quote.'}</small></div>${icon('chevron-right','sm')}</button></div>
 <section class="quote-step"><div><h3>Ready to investigate?</h3><p>Ask for the same sailing, cabin and inclusions. Confirm the final price for two UK residents.</p></div><div class="source-actions">${sourceLinks(r)}</div><details class="chart-data"><summary>What to confirm before booking</summary><div class="quote-checks">${['Available cabin','Exact cabin grade','UK eligibility','Mandatory charges','All-Inclusive terms','Cancellation rules'].map(x=>`<div><span>${x}</span><span class="check-needed">Confirm</span></div>`).join('')}</div></details></section>
 <details class="technical-details"><summary>Price basis, source and dates</summary><p>${esc(tripEndLabel(r))}. ${r.end_date_basis==='published_seller_dates'?'This end date is listed by the matched seller; confirm it before booking. '+withLink(r.end_date_source_url,'Listed itinerary dates'):'The end date is estimated conservatively as departure plus the published duration. Confirm the exact itinerary end date. A flight or transfer can require extra time.'}</p><p>Category ${esc(f?.column||'unknown')}. Source checked ${esc(dateTime(DATA.feed.last_confirmed_at||DATA.feed.observed_at))}. The estimate doubles a published per-person fare value; taxes, occupancy and final payable costs require confirmation.</p>${r.promotion?`<p>Published promotion: ${esc(r.promotion)}</p>`:''}<p>Lines join actual observations. Prices between checks are unknown. Historical advertisements from other sellers or packages are kept separate.</p></details><details class="chart-data"><summary>Preview the quote request</summary><pre class="quote-preview">${esc(makeQuote(r,f?.column))}</pre></details>`;
}
function renderOverviewChart(){const canvas=$('overviewPriceChart');if(!canvas)return;window.Chart?.getChart(canvas)?.destroy();if(!window.Chart){canvas.hidden=true;return}const f=detailRate(),values=observedPoints(DETAIL,f?.column),c=palette(),options=baseChart();options.scales.x={...options.scales.x,type:'linear',ticks:{...options.scales.x.ticks,callback:v=>shortDay(v)}};options.scales.x.min=Date.parse(values[0][0]);options.scales.x.max=Date.parse(values.at(-1)[0]);options.scales.y.ticks.maxTicksLimit=5;options.scales.y.title={display:true,text:'Estimated cruise price for two',color:c.muted,font:{size:10}};options.plugins.tooltip.callbacks={title:a=>dateTime(a[0].raw.x),label:a=>money(a.raw.y,true)+' for two · estimate'};detailChart=new Chart(canvas,{type:'line',data:{datasets:[{data:values.map(p=>({x:Date.parse(p[0]),y:p[1]*2})),borderColor:c.blue,backgroundColor:c.blue,borderWidth:2,stepped:'before',pointRadius:4,pointHoverRadius:6,fill:false}]},options});}

function sourceLinks(r){const seen=new Set(),links=[];for(const s of [...(r.retail_prices||[]),...(r.sources||[])]){const u=safeURL(s.url);if(!u||seen.has(u))continue;if(s.scope&&s.scope!=='dated_sailing')continue;seen.add(u);links.push(withLink(u,s.provider||'Seller source'));if(links.length===3)break}links.push(withLink('https://www.cruiseline.co.uk/cruise-lines/windstar-cruises/','The Cruise Line search'));links.push(withLink('https://www.google.com/search?q='+encodeURIComponent('"'+r.cruise_id+'" Windstar quote'),'Search exact cruise ID'));return links.join('');}
function pricesHTML(r){const f=detailRate(),retail=[...(r.retail_prices||[])].sort((a,b)=>String(a.provider).localeCompare(String(b.provider))||(a.fare_pp_pence||Infinity)-(b.fare_pp_pence||Infinity));
 return `<h3 class="detail-heading" style="margin-top:0">Published cabin guides</h3><p class="section-caption">The supplier’s category codes. Confirm the exact cabin and full price with your seller. ${info('cabin','Understand supplier cabin columns')}</p><div class="table-scroll"><table class="data-table"><caption class="sr-only">Published raw supplier fare cells for ${esc(r.itinerary)}</caption><thead><tr><th scope="col">Supplier column</th><th scope="col">Supplier value, assumed per person</th><th scope="col">Estimated for 2</th><th scope="col">History</th></tr></thead><tbody>${r.fares.map(([c,n])=>`<tr ${c===f?.column?'class="selected-row"':''}><td>${esc(c)}${c===f?.column?'<small>Current guide selection</small>':''}</td><td class="money">${money(n,true)}</td><td class="money">${money(n*2,true)}</td><td><button class="text-link" data-action="detail-tab" data-tab="history" data-column="${esc(c)}">View ${icon('arrow-right','sm')}</button></td></tr>`).join('')}</tbody></table></div><div class="notice">Price units, occupancy, taxes and fees still require confirmation. The multiplication above is a research guide, not the seller's final two-person price.</div><h3 class="detail-heading">Compare sellers for this departure</h3><p class="section-caption">Retained advertisements matched to ship, date and duration. Cabin grades, inclusions and final terms still need matching. ${info('agency','About seller comparisons')}</p>${retail.length?`<div class="table-scroll"><table class="data-table"><caption class="sr-only">Dated, unverified seller advertisements</caption><thead><tr><th scope="col">Seller & observation</th><th scope="col">Advertised category</th><th scope="col">Per person</th><th scope="col">Evidence</th></tr></thead><tbody>${retail.map(v=>{const age=(Date.now()-Date.parse(v.observed_at))/3600000;return `<tr><td>${withLink(v.url,v.provider)}<small>${esc(dateTime(v.observed_at))}${age>48?' · Recheck age':''}</small></td><td>${esc(v.cabin)}<small>${esc(String(v.basis||'advertisement').replaceAll('_',' '))}</small></td><td class="money">${money(v.fare_pp_pence,true)}${Number.isFinite(v.pair_total_pence)?`<small>Explicit pair: ${money(v.pair_total_pence,true)}</small>`:''}</td><td>${v.price_conflict?'<span class="check-needed">Conflicting values</span>':'Unverified advert'}<small>Availability not confirmed</small></td></tr>`}).join('')}</tbody></table></div>`:`<div class="notice">No exact matched seller advertisement is stored for this voyage. Use the seller links or copy a quote request.</div>`}<div class="notice">Shared provider brands are not independent comparisons. Do not multiply a seller's rounded per-person headline when it supplies an explicit two-adult quote.</div>`;
}
function dateOptions(r){return PRODUCTS.filter(p=>p.family_id===r.family_id&&F.withinDates(p,state)).sort((a,b)=>a.departure.localeCompare(b.departure))}
function tripEndLabel(r){const end=F.endDate(r);return end?(r.end_date_basis==='published_seller_dates'?'Ends ':'Est. end ')+day(end):'End date unavailable'}
function datesHTML(r){const a=dateOptions(r),unique=new Set(a.map(x=>x.departure)).size,limited=!!(state.from||state.to);return `<div class="chart-title"><div><h3>${unique} ${unique===1?'date':'dates'}${limited?' within your travel window':''}. One itinerary family.</h3><p>Same ship, itinerary, published duration and product type. ${info('otherdates','About comparing different departure dates')}</p></div></div>${a.length>1?'<div class="chart-wrap"><canvas id="dateChart" role="img" aria-label="Estimated guides for two across departure dates that fit your travel window"></canvas></div>':`<div class="notice">${a.length===0?'No dates for this itinerary start and finish within your selected window. Broaden your travel dates to see more.':limited?'One departure fits your travel window.':'One future departure is listed for this itinerary.'}</div>`}<p class="section-caption">${limited?'Your full cruise must fit the selected dates. ':''}Estimated end dates are marked. Allow extra time for flights and transfers. Guides use each departure’s lowest published category, which can differ.</p>${a.length?`<div class="table-scroll"><table class="data-table"><caption class="sr-only">Itinerary dates fitting the selected full-cruise travel window</caption><thead><tr><th scope="col">Departure</th><th scope="col">Cruise ends</th><th scope="col">Lowest guide for 2</th><th scope="col">Seller evidence</th></tr></thead><tbody>${a.map(v=>`<tr ${v.id===r.id?'class="selected-row"':''} data-trip-start="${esc(v.departure)}" data-trip-end="${esc(F.endDate(v)||'')}"><td><button class="date-table-button" data-action="voyage" data-id="${esc(v.id)}">${esc(day(v.departure))}${v.id===r.id?' · Selected':''}</button></td><td>${esc(tripEndLabel(v))}</td><td class="money">${money(Number.isFinite(v.low_pence)?v.low_pence*2:NaN,true)}</td><td>${v.retail_advert_count||0} retained records</td></tr>`).join('')}</tbody></table></div>`:''}`;}

function supplierHistoryHTML(r){const cols=r.fares.map(x=>x[0]);if(!cols.includes(DETAIL_COLUMN))DETAIL_COLUMN=cols[0]||'';const h=r.price_history?.[DETAIL_COLUMN],pts=(h?.points||[]).filter(p=>Number.isFinite(p[1])&&Number.isFinite(Date.parse(p[0]))).sort((a,b)=>Date.parse(a[0])-Date.parse(b[0]));
 return `<div class="price-column-select"><label for="historyColumn">Choose a price category</label><select id="historyColumn">${cols.map(c=>`<option ${c===DETAIL_COLUMN?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select>${info('drop','Understand recorded price drops')}</div><p class="section-caption">Recorded supplier values for this category, used as per-person estimates. Confirm the price basis and final two-person quote with the seller. ${pts.length} actual observation${pts.length===1?'':'s'}${pts.length?' from '+esc(day(pts[0][0]))+' to '+esc(day(pts.at(-1)[0])):''}.</p>${pts.length>=2?`<div class="history-kpis"><div><span>First recorded price</span><strong>${money(pts[0][1])}</strong></div><div><span>Lowest recorded price</span><strong>${money(Math.min(...pts.map(x=>x[1])))}</strong></div><div><span>Latest recorded price</span><strong>${money(pts.at(-1)[1])}</strong></div></div><div class="chart-wrap history-chart"><canvas id="historyChart" role="img" aria-label="Actual observed GBP values for supplier column ${esc(DETAIL_COLUMN)}"></canvas></div><p class="data-state">The stepped line only joins recorded checks; prices between checks are unknown. History starts with ORION's first observation, not the beginning of the supplier's sale.</p>`:`<div class="empty-state">${icon('chart-no-axes-combined')}<h3>${pts.length?'One observation. No trend yet.':'No history for this column yet.'}</h3><p>At least two dated checks are needed to show a price change. ORION will not invent earlier values.</p></div>`}${pts.length?`<details class="chart-data" ${pts.length<2?'open':''}><summary>Read all ${pts.length} chart values</summary><div class="table-scroll"><table class="data-table"><caption class="sr-only">Each actual plotted price observation</caption><thead><tr><th scope="col">Observed at, UK time</th><th scope="col">Supplier value, assumed per person</th></tr></thead><tbody>${pts.map(p=>`<tr><td>${esc(dateTime(p[0]))}</td><td class="money">${money(p[1],true)}</td></tr>`).join('')}</tbody></table></div></details>`:''}<div class="notice">A raw drop is not a verified saving against today's other sellers. Confirm the exact cabin, final UK payable total and inventory before booking. ${withLink(DATA.feed.source_url,'Original supplier feed')}</div>`;
}
function renderVoyage({replaceURL=false}={}){if(!DETAIL)return;const renderID=++DETAIL_RENDER;destroyDetailChart();const r=DETAIL;const tabs=[['overview','Overview'],['prices','Cabins & sellers'],['dates','All dates'],['history','Price history']];$('voyageContent').innerHTML=`<div class="voyage-head visual-detail region-${esc(regionScene(r.region).key)}">${regionScene(r.region).image?`<img class="detail-photo" src="assets/imagery/${regionScene(r.region).image}" alt="" width="900" height="500">`:""}<div class="voyage-kicker">${icon('ship')}${esc(r.ship)} <span class="detail-divider">/</span> ${esc(regionLabel(r.region))}</div><h2 id="voyageTitle" tabindex="-1">${esc(r.itinerary)}</h2><button class="icon-btn close voyage-close" data-close="voyageDialog" aria-label="Close voyage">${icon('x')}</button><div class="voyage-context"><span>${icon('calendar-days')}${esc(day(r.departure))}</span><span data-end-date="${esc(F.endDate(r)||'')}">${esc(tripEndLabel(r))}</span><span>${icon('clock-3')}${r.duration} published days</span></div>${regionScene(r.region).image?'<span class="detail-photo-note">Regional inspiration</span>':''}<div class="detail-route-strip"><span><small>DEPARTURE</small>${esc(r.from_port)}</span>${icon('arrow-right')}<span><small>ARRIVAL</small>${esc(r.to_port)}</span></div></div><div class="voyage-tabs" role="tablist" aria-label="Voyage detail">${tabs.map(([k,t])=>`<button role="tab" id="tab-${k}" data-action="detail-tab" data-tab="${k}" aria-selected="${DETAIL_TAB===k}" aria-controls="voyagePane" tabindex="${DETAIL_TAB===k?'0':'-1'}">${t}</button>`).join('')}</div><div class="voyage-pane" id="voyagePane" role="tabpanel" aria-labelledby="tab-${DETAIL_TAB}">${!F.withinDates(r,state)?'<div class="notice outside-travel-window" role="status">This voyage falls outside your selected travel dates. It is not included in your filtered results.</div>':''}${DETAIL_TAB==='prices'?pricesHTML(r):DETAIL_TAB==='dates'?datesHTML(r):DETAIL_TAB==='history'?historyHTML(r):overviewHTML(r)}</div><div class="voyage-footer" id="voyageFooter"></div>`;updateVoyageFooter();writeURL(replaceURL);requestAnimationFrame(()=>{if(renderID!==DETAIL_RENDER||!$('voyageDialog').open)return;if(!$('voyageDialog').contains(document.activeElement))$('voyageTitle')?.focus({preventScroll:true});if(DETAIL_TAB==='overview')renderOverviewChart();if(DETAIL_TAB==='history')renderHistoryChart();if(DETAIL_TAB==='dates')renderDateChart()});}
function updateVoyageFooter(){if(!DETAIL||!$('voyageFooter'))return;const r=DETAIL;$('voyageFooter').innerHTML=`<div>${saveButton(r,true)}<button class="button quiet" data-action="watch-voyage" aria-label="Watch price for this exact voyage">${icon('clock-3')}<span class="label-hide">Watch price</span></button><button class="button quiet" data-action="share-voyage" aria-label="Share this voyage and evidence view">${icon('share-2')}<span class="label-hide">Share</span></button>${compareControl(r)}</div><div class="quote-action"><button class="button primary" data-action="quote" aria-describedby="quoteCopyHelp">${icon('copy')}Copy quote request</button><span id="quoteCopyHelp">Copies a draft. Nothing is sent.</span></div>`;}
function changeDetailTab(tab,column){DETAIL_TAB=['overview','prices','dates','history'].includes(tab)?tab:'overview';if(column)DETAIL_COLUMN=column;renderVoyage();requestAnimationFrame(()=>$('tab-'+DETAIL_TAB)?.focus({preventScroll:true}));}
function baseChart(){const c=palette();return {responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{backgroundColor:c.ink,titleColor:c.bg,bodyColor:c.bg,padding:11,displayColors:false,titleFont:{size:11},bodyFont:{size:11}}},scales:{x:{grid:{display:false},border:{color:c.line},ticks:{color:c.muted,font:{size:10},maxTicksLimit:7}},y:{grid:{color:c.line,drawTicks:false},border:{display:false},ticks:{color:c.muted,font:{size:10},padding:8,callback:v=>fmtGBP.format(v/100)}}}}}
function renderHistoryChart(){if(HISTORY_SOURCE==='archive'){renderArchiveChart();return}const canvas=$('historyChart');if(!canvas)return;window.Chart?.getChart(canvas)?.destroy();if(!window.Chart){canvas.replaceWith(Object.assign(document.createElement('p'),{className:'notice',textContent:'The chart library did not load. The exact observation table below is still available.'}));return}const pts=(DETAIL.price_history?.[DETAIL_COLUMN]?.points||[]).filter(p=>Number.isFinite(p[1])&&Number.isFinite(Date.parse(p[0]))).map(p=>({x:Date.parse(p[0]),y:p[1]})).sort((a,b)=>a.x-b.x);const c=palette(),opt=baseChart();opt.scales.x={...opt.scales.x,type:'linear',ticks:{...opt.scales.x.ticks,callback:v=>shortDay(v)}};opt.scales.y.title={display:true,text:'Supplier value (GBP); confirm price basis',color:c.muted,font:{size:10}};opt.plugins.tooltip.callbacks={title:items=>dateTime(items[0].raw.x),label:ctx=>DETAIL_COLUMN+': '+money(ctx.raw.y,true)};detailChart=new Chart(canvas,{type:'line',data:{datasets:[{data:pts,borderColor:c.blue,backgroundColor:c.blue,borderWidth:2,stepped:'before',pointRadius:4,pointHoverRadius:6,fill:false}]},options:opt});}
function renderDateChart(){const canvas=$('dateChart');if(!canvas||!window.Chart)return;Chart.getChart(canvas)?.destroy();const options=dateOptions(DETAIL).filter(r=>Number.isFinite(r.low_pence)),points=options.map(r=>({x:Date.parse(r.departure+'T12:00:00Z'),y:r.low_pence*2,id:r.id}));const c=palette(),opt=baseChart();opt.scales.x={...opt.scales.x,type:'linear',ticks:{...opt.scales.x.ticks,callback:v=>new Date(v).toLocaleDateString('en-GB',{month:'short',year:'2-digit',timeZone:'UTC'})}};opt.scales.y.title={display:true,text:'Lowest guide for two',color:c.muted,font:{size:10}};opt.plugins.tooltip.callbacks={title:items=>day(items[0].raw.x),label:ctx=>money(ctx.raw.y,true)+' estimated for two',afterLabel:()=> 'Select to open this departure'};opt.onClick=(e,els)=>{if(els.length)openVoyage(points[els[0].index].id)};detailChart=new Chart(canvas,{type:'scatter',data:{datasets:[{data:points,pointRadius:4,pointHoverRadius:7,backgroundColor:c.blue}]},options:opt});}
function renderCalendar(a=filtered()){if(!CALENDAR_OPEN)return;if(calendarChart){calendarChart.destroy();calendarChart=null}const year=$('calendarYear').value,months=Array.from({length:12},(_,i)=>{const key=year+'-'+String(i+1).padStart(2,'0'),group=a.filter(r=>F.withinDates(r,{from:key+'-01',to:strTime(Date.UTC(Number(year),i+1,0))})&&Number.isFinite(fare(r)?.amount));return {key,label:new Date(Number(year),i,1).toLocaleDateString('en-GB',{month:'short'}),min:group.length?Math.min(...group.map(r=>fare(r).amount*2)):null,count:group.length}});
 $('calendarTable').innerHTML=`<div class="table-scroll"><table class="data-table"><caption class="sr-only">Lowest guide for cruises starting and ending within each month of ${esc(year)}</caption><thead><tr><th>Month</th><th>Matching departures</th><th>Lowest guide for two</th></tr></thead><tbody>${months.map(m=>`<tr><td>${m.count?`<button class="date-table-button" data-month="${m.key}">${m.label} ${year}</button>`:m.label+' '+year}</td><td>${m.count}</td><td class="money">${m.min!==null?money(m.min):'No matching departures'}</td></tr>`).join('')}</tbody></table></div>`;
 const good=months.some(m=>m.count);$('calendarChart').hidden=!good;$('calendarFallback').innerHTML=good?'':'<div class="notice">No matching departures in this year. Choose another calendar year or broaden your date filters.</div>';if(!good)return;if(!window.Chart){$('calendarFallback').innerHTML='<p class="notice">The chart could not load. All monthly values are available in the data table.</p>';$('calendarChart').hidden=true;return}const c=palette(),opt=baseChart();opt.scales.y.beginAtZero=true;opt.plugins.tooltip.callbacks={title:items=>months[items[0].dataIndex].label+' '+year,label:ctx=>money(ctx.raw)+' estimated for two',afterLabel:ctx=>months[ctx.dataIndex].count+' matching products · Select month'};opt.onClick=(e,els)=>{if(els.length&&months[els[0].index].count)chooseMonth(months[els[0].index].key)};calendarChart=new Chart($('calendarChart'),{type:'bar',data:{labels:months.map(m=>m.label),datasets:[{data:months.map(m=>m.min),backgroundColor:c.blue,borderRadius:4,maxBarThickness:36}]},options:opt});}
function chooseMonth(month){const [y,m]=month.split('-').map(Number);state.from=month+'-01';state.to=strTime(Date.UTC(y,m,0));state.page=1;render();toast('Showing cruises that start and finish in '+new Date(y,m-1,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'}));}
function openComparison(){const rows=[...compared].map(id=>BY_ID.get(id)).filter(Boolean);if(!rows.length){toast('Choose up to three voyages to compare.');return}const cells=[['Departure',r=>day(r.departure)],['Cruise end',r=>tripEndLabel(r)],['Published duration',r=>r.duration+' days'],['Route',r=>r.from_port+' → '+r.to_port],['Type',r=>r.kind],['Lowest cruise guide for 2',r=>money(Number.isFinite(r.low_pence)?r.low_pence*2:NaN,true)],['Recorded change',r=>r.drop?.pct>0?'Up to '+pct(r.drop.pct)+' in '+r.drop.column:'No recorded decrease'],['Seller evidence',r=>r.retail_advert_count+' retained advertisements'],['Available cabin confirmed?',()=> 'Not verified'],['Final UK costs confirmed?',()=> 'Not verified']];$('comparisonContent').innerHTML=`<div class="table-scroll"><table class="data-table comparison-table"><caption class="sr-only">Comparing selected voyages, not claiming like-for-like savings</caption><thead><tr><th scope="col">What matters</th>${rows.map(r=>`<th scope="col"><div class="compare-title">${esc(r.itinerary)}</div><small>${esc(r.ship)}</small></th>`).join('')}</tr></thead><tbody>${cells.map(([label,fn])=>`<tr><th scope="row">${label}</th>${rows.map(r=>`<td class="${label.startsWith('Lowest')?'table-amount':''}">${esc(fn(r))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Next step</th>${rows.map(r=>`<td><button class="text-link" data-action="compare-open-voyage" data-id="${esc(r.id)}">View voyage ${icon('arrow-right','sm')}</button></td>`).join('')}</tr></tbody></table></div><div class="notice">Different departures, cabins and packages are different purchases. This comparison helps build a shortlist; it does not prove a market saving. Flights and unconfirmed mandatory costs are not added to these guides.</div>`;modalOpen('comparisonDialog');}
function renderOffers(){if(!DATA)return;const show=$('showExcluded').checked,all=DATA.offers||[],rows=all.filter(x=>show||x.decision!=='excluded');$('offerGrid').innerHTML=rows.map(x=>{const label={needs_verification:'Needs verification',excluded:'Excluded for now',eligible_unpriced:'Eligible route · no quote',already_captured:'Already included',priced_candidate:'Quoted candidate · recheck'}[x.decision]||'Needs verification';return `<article class="offer-card"><div class="offer-top"><span>${esc(String(x.method||'public offer').replaceAll('_',' '))}</span><span>${esc(x.campaign_state||'unknown')}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><span class="offer-state">${label}</span><div class="offer-dimensions"><div><span>Evidence</span><strong>${esc(String(x.evidence_level||'unknown').replaceAll('_',' '))}</strong></div><div><span>Eligibility</span><strong>${esc(x.eligibility||'unknown')}</strong></div><div><span>Stage reached</span><strong>${esc(String(x.transaction_stage||'not tested').replaceAll('_',' '))}</strong></div></div><p class="offer-next"><strong>Next check:</strong> ${esc(x.next_action)}</p><div class="source-actions">${(x.sources||[]).map(s=>withLink(s.url,'Read source terms')).join('')}</div><div class="offer-bottom"><span>Observed ${esc(day(x.checked_on))}</span><span>No discount applied</span></div></article>`}).join('')||'<div class="empty-state"><h3>No offer routes in this edition.</h3><p>This does not establish that no offers exist.</p></div>';}
function renderFreshness(){
 if(!DATA)return;
 const f=DATA.feed,status=C.freshness(DATA),issues=[];
 if(!status.confirmed)issues.push(status.legacyFallback?'Only a historical price snapshot is recorded; a recent check is unverified.':'The latest price check is unverified.');
 else if(!status.feedFresh)issues.push('Price checks are over six hours old.');
 if(!status.editionFresh)issues.push(status.editionAge===null?'The website edition date is unverified.':'This website edition is over six hours old.');
 $('snapshotLabel').textContent=status.confirmed?(status.feedFresh?'Prices checked ':'Price checks overdue · ')+day(f.last_confirmed_at):'Price check unverified';
 const line=$('freshnessLine');if(line)line.innerHTML=`<span>${icon('clock-3')}Price check: ${status.confirmed?esc(dateTime(f.last_confirmed_at)):'Unverified'}</span><span>Website edition: ${status.editionAge===null?'Unverified':esc(dateTime(DATA.built_at))}</span><button class="inline-link" data-action="status">Dates & sources</button>`;
 const banner=$('staleBanner');if(banner){banner.hidden=!issues.length;banner.setAttribute('role','status');if(issues.length)banner.innerHTML=`${icon('clock-3')}<span>${esc(issues.join(' '))} Recheck with a seller before acting.</span><button class="inline-link" data-action="status">Update status</button>`;}
}

function openStatus(){if(!DATA){$('statusTitle').textContent='Prices could not load';$('statusContent').innerHTML='<p>No successful price check is being claimed. Reload the published edition to try again.</p>';modalOpen('statusDialog');return}const f=DATA.feed,next=Date.parse(f.next_eligible_at),waiting=Number.isFinite(next)&&next>Date.now();$('statusTitle').textContent='How fresh are these prices?';$('statusContent').innerHTML=`<div class="update-answer"><span class="eyebrow">AT A GLANCE</span><h3>The website is a saved edition.</h3><p>Price collection runs automatically. Publishing that collected data to this website still requires a manual step.</p></div><ol class="update-steps"><li><span class="step-number">1</span><div><strong>Collect current prices</strong><p>The main cruise-price feed has a ${Number(f.minimum_interval_hours)||20}-hour minimum between checks. The hourly collector checks sources when they are due and the computer is online.</p><small>Last confirmed cruise-price check: ${esc(C.freshness(DATA).confirmed?dateTime(f.last_confirmed_at):'Unverified')}.</small></div><span class="stage-label">Automatic</span></li><li><span class="step-number">2</span><div><strong>Keep the history and compare</strong><p>Collected prices are stored with dates. Different cabins, sellers and packages stay separate.</p><small>Latest retained seller observation: ${esc(dateTime(DATA.seller_latest_observed_at))}.</small></div><span class="stage-label">Automatic</span></li><li><span class="step-number">3</span><div><strong>Publish to this website</strong><p>This final step is currently manual. A scheduled research task does not publish a new website edition.</p><small>This edition was prepared ${esc(dateTime(DATA.built_at))}.</small></div><span class="stage-label stage-manual">Manual</span></li></ol><div class="next-check-note"><strong>${waiting?'Next permitted cruise-price check':'The next cruise-price check is due'}</strong><p>${Number.isFinite(next)?esc(dateTime(f.next_eligible_at)):'Next time is not recorded in this edition.'}${waiting?' or later, when the hourly collector runs.':' Check the latest published edition for newer results.'}</p><small>This is an earliest check time, not a guaranteed update or publication time.</small></div><div class="notice">Automatic website publication: <strong>Not enabled.</strong> Reloading reads the latest published edition; it cannot fetch prices or confirm live cabins.</div><div class="status-actions"><button class="button secondary" data-action="reload">${icon('refresh-cw')}Reload published prices</button><button class="button quiet" data-action="help" data-topic="freshness">Read the update guide</button></div><details class="technical-details"><summary>Detailed dates and collection status</summary><dl class="status-rows"><div><dt>Price-content snapshot</dt><dd>${esc(dateTime(f.observed_at))}</dd></div><div><dt>Latest source attempt</dt><dd>${esc(dateTime(f.last_attempt_at))}<small>${esc(f.last_attempt_status||'Unknown')}</small></dd></div><div><dt>Last successful collector cycle</dt><dd>${esc(dateTime(DATA.collector_last_success))}<small>May relate to another source.</small></dd></div><div><dt>Current edition</dt><dd>${esc(DATA.release)} · ${fmtNum.format(PRODUCTS.length)} catalogue products</dd></div></dl></details>`;modalOpen('statusDialog');}

function exportSaved(){const rows=[...saved].map(id=>BY_ID.get(id)).filter(Boolean);if(!rows.length){toast('Save a voyage before exporting.');return}const csvField=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const fields=['Ship','Itinerary','Departure','Cruise end','End date basis','Published days','Supplier cruise ID','Lowest guide for two GBP','Guide status','Feed observed UTC','Voyage link'];const lines=[fields,...rows.map(r=>[r.ship,r.itinerary,r.departure,F.endDate(r)||'',r.end_date_basis||'estimated_from_published_duration',r.duration,r.cruise_id,Number.isFinite(r.low_pence)?(r.low_pence*2/100).toFixed(2):'','UNVERIFIED estimate; final costs and inventory unknown',DATA.feed.observed_at,new URL('?voyage='+encodeURIComponent(r.id),base).href])];const blob=new Blob(['\uFEFF'+lines.map(a=>a.map(csvField).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download='ORION-shortlist-'+today+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Shortlist exported with source dates and price caveats.');}

