 if(action==='share-voyage'&&DETAIL_ID){const url=new URL(base);url.searchParams.set('voyage',DETAIL_ID);if(DETAIL_TAB!=='overview')url.searchParams.set('tab',DETAIL_TAB);if(DETAIL_TAB==='history'&&HISTORY_SOURCE==='supplier'&&DETAIL_COLUMN)url.searchParams.set('history_column',DETAIL_COLUMN);if(DETAIL_TAB==='history'&&HISTORY_SOURCE==='archive'){url.searchParams.set('history_source','archive');url.searchParams.set('history_range',HISTORY_RANGE);url.searchParams.set('history_series',ARCHIVE_SERIES)}await copyText(url.href,'Voyage and selected evidence view copied.');return}
